/** Original region member cards, custom membership and atomic group/detach intents. */
@Composable fun RovaiCanvasRegion(model:RovaiWorkspaceViewModel,boardId:String,node:JsonObject,onClose:()->Unit){
    val state=model.state.collectAsState().value;val scope=rememberCoroutineScope();val generation=remember{model.connectionGeneration};val id=node.coreText("id");val owner="canvas-region-op:$boardId:$id"
    var graph by remember{mutableStateOf<JsonObject?>(null)};var current by remember{mutableStateOf(node)};var rows by remember{mutableStateOf<List<JsonObject>>(emptyList())};var groups by remember{mutableStateOf<List<JsonObject>>(emptyList())};var folders by remember{mutableStateOf<Map<String,RovaiCanvasFolderRelation>>(emptyMap())};var cursor by remember{mutableStateOf<RovaiCanvasReferenceCursor?>(null)};var loaded by remember{mutableStateOf(false)};var busy by remember{mutableStateOf(false)};var issue by remember{mutableStateOf<String?>(null)};var search by remember{mutableStateOf("")};var selected by remember{mutableStateOf<Set<String>>(emptySet())};var target by remember{mutableStateOf("")};var opening by remember{mutableStateOf<JsonObject?>(null)}
    val data=current["data"].coreObject();val custom=data.coreText("kind")=="custom";val resolution=resolveCanvasRegion(current,rows,loaded&&cursor==null,groups,folders);val blocked=busy||graph==null||state.busy||state.pending!=null||generation!=model.connectionGeneration;val stale=graph?.get("board").coreObject().coreLong("revision")!=state.boards.firstOrNull{it.coreText("id")==boardId}?.coreLong("revision")
    suspend fun page(reset:Boolean){if(reset){rows=emptyList();cursor=null;loaded=false};val next=readCanvasReferencePage(model,if(reset)null else cursor);require(generation==model.connectionGeneration);require(next.items.none{item->rows.any{it.coreText("threadId")==item.coreText("threadId")}}){"对话目录分页出现重复，请重新载入"};rows=rows+next.items;cursor=next.next;loaded=true}
    suspend fun load(){val next=model.query(RovaiOperation.CANVAS_NODES_SNAPSHOT,buildJsonObject{put("boardId",boardId)}).coreObject();val region=next["nodes"].coreArray().firstOrNull{it.coreText("id")==id}?:error("原区域已删除");val grouping=model.query(RovaiOperation.NAVIGATION_PROJECTGROUPS,buildJsonObject{put("action","get")}).coreObject()["projectGroups"].coreArray();val related=readCanvasFolderRelations(model,canvasRegionRoots(region,grouping));require(generation==model.connectionGeneration);current=region;graph=next;groups=grouping;folders=related;page(true)}
    fun refresh(){if(busy)return;busy=true;scope.launch{try{load();issue=null}catch(cancelled:CancellationException){throw cancelled}catch(error:Exception){issue=error.message}finally{busy=false}}}
    fun mutate(mutation:JsonObject){if(blocked||stale)return;val snapshot=graph?:return;val body=mutation.toString();busy=true;scope.launch{try{model.saveBody(owner,body);model.rememberBody(owner,body);require(generation==model.connectionGeneration);model.executeOwned(RovaiOperation.CANVAS_NODES_APPLY,buildJsonObject{put("commandId",UUID.randomUUID().toString());putJsonObject("command"){put("boardId",boardId);put("expectedRevision",snapshot["board"].coreObject().coreLong("revision"));put("mutation",mutation)}},owner,body)}catch(error:Exception){issue=error.message}finally{busy=false}}}
    LaunchedEffect(id,state.lastResult){busy=true;try{load()}catch(cancelled:CancellationException){throw cancelled}catch(error:Exception){issue=error.message}finally{busy=false}}
    Dialog(onDismissRequest={if(!busy)onClose()},properties=DialogProperties(usePlatformDefaultWidth=false,dismissOnClickOutside=false)){Surface(Modifier.fillMaxSize(),color=CodegTheme.colors.bgElevated){Column{
        Row(Modifier.fillMaxWidth().padding(12.dp)){Text(data.coreText("title").ifEmpty{rovaiCanvasKindNames[data.coreText("kind")]?:"区域"},Modifier.weight(1f),style=MaterialTheme.typography.titleMedium);TextButton(enabled=!busy,onClick=onClose){Text("关闭")}}
        LazyColumn(Modifier.weight(1f),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){
            item{if(busy)LinearProgressIndicator(Modifier.fillMaxWidth());issue?.let{Text(it,color=CodegTheme.colors.danger)};resolution.issue?.let{Text(it,color=CodegTheme.colors.textSecondary)};if(stale)Text("画布已有其他修改，请重新读取后操作。",color=CodegTheme.colors.danger);OutlinedTextField(search,{search=it},Modifier.fillMaxWidth(),label={Text("搜索区域会话")});Text("${resolution.members.size} 个已载入会话"+(if(resolution.complete)""else" · 尚未完整载入"),style=MaterialTheme.typography.bodySmall,color=CodegTheme.colors.textSecondary);TextButton(enabled=!busy,onClick={refresh()}){Text("重新读取区域与会话")}}
            resolution.members.filter{search.isBlank()||it.label.contains(search,true)}.forEach{member->item(key=member.key){Surface(shape=MaterialTheme.shapes.medium,color=CodegTheme.colors.bg){Column(Modifier.fillMaxWidth().padding(12.dp)){
                Row{Checkbox(member.key in selected,enabled=!blocked&&(member.key in selected||selected.size<200)&&member.available==true,onCheckedChange={checked->selected=if(checked)selected+member.key else selected-member.key});Text(member.label,Modifier.weight(1f),style=MaterialTheme.typography.titleSmall)}
                Row{TextButton(enabled=!busy&&member.available==true,onClick={opening=member.reference}){Text("打开原会话")};TextButton(enabled=!blocked&&!stale&&member.available==true,onClick={val x=(data["x"]as?JsonPrimitive)?.doubleOrNull?:0.0;val y=(data["y"]as?JsonPrimitive)?.doubleOrNull?:0.0;val width=(data["width"]as?JsonPrimitive)?.doubleOrNull?:496.0;mutate(buildJsonObject{put("type","detach");put("regionId",id);put("conversation",member.reference);put("x",x+width+48);put("y",y)})}){Text("拆出卡片")};if(custom)TextButton(enabled=!blocked&&!stale,onClick={mutate(buildJsonObject{put("type","update");put("nodeId",id);putJsonObject("patch"){put("memberRemove",member.reference)}});selected=selected-member.key}){Text("移出分组")}}
            }}}}
            if(custom)item{val all=canvasReferenceChoices(rows);val existing=resolution.members.map{it.key}.toSet();RovaiCanvasChoice("添加已有会话","",all.filter{it.key !in existing}.map{it.key to it.label},!blocked&&!stale){key->all.firstOrNull{it.key==key}?.let{choice->mutate(buildJsonObject{put("type","update");put("nodeId",id);putJsonObject("patch"){put("memberAdd",choice.reference)}})}}}
            item{if(cursor!=null)TextButton(enabled=!busy,onClick={busy=true;scope.launch{try{page(false)}catch(error:Exception){issue=error.message}finally{busy=false}}}){Text("载入更多会话")}}
            item{Text("选中的会话 · ${selected.size}",style=MaterialTheme.typography.titleSmall);RovaiCanvasChoice("目标分组",target,listOf("" to "新建自定义分组")+graph?.get("nodes").coreArray().filter{it.coreText("id")!=id&&it["data"].coreObject().coreText("kind")=="custom"}.map{it.coreText("id") to it["data"].coreObject().coreText("title").ifEmpty{"自定义分组"}},!blocked){target=it};Button(enabled=!blocked&&!stale&&selected.isNotEmpty()&&graph?.get("memberTransferVersion")==JsonPrimitive(1),onClick={val members=resolution.members.filter{it.key in selected&&it.available==true};if(members.size!=selected.size){issue="所选会话来源已变化，请重新选择"}else{val x=(data["x"]as?JsonPrimitive)?.doubleOrNull?:0.0;val y=(data["y"]as?JsonPrimitive)?.doubleOrNull?:0.0;val count=(members.size+1)/2;mutate(buildJsonObject{put("type","group");put("targetNodeId",if(target.isEmpty())JsonNull else JsonPrimitive(target));put("newRegion",if(target.isNotEmpty())JsonNull else buildJsonObject{put("kind","custom");put("x",x-12);put("y",y-52);put("width",484);put("height",64+count*132+(count-1).coerceAtLeast(0)*12)});put("conversations",JsonArray(members.map{it.reference}));put("consumeNodeIds",JsonArray(emptyList()));put("sourceMembers",JsonArray(members.map{buildJsonObject{put("regionId",id);put("conversation",it.reference)}}))})}}){Text(if(target.isEmpty())"归为新分组"else"转移到所选分组")};Text("自定义分组会移出原成员；工程、队员等自动区域保留其派生关系。不会移动实际会话或文件。",style=MaterialTheme.typography.bodySmall,color=CodegTheme.colors.textSecondary)}
        }
    }}}
    opening?.let{reference->RovaiCanvasConversationNode(model,boardId,current,memberReference=reference){opening=null}}
}
